import db from "./db";
import type { JsonObject } from "@remix-run/router"; // generic type for JSON data

/**
 * Insert a backup record into the local SQLite database.
 * @param data - JSON-serializable object representing the backup payload.
 * @returns The autogenerated ID of the new backup row.
 */
export function addBackup(data: JsonObject): number {
  const stmt = db.prepare(`INSERT INTO backups (data) VALUES (?)`);
  const info = stmt.run(JSON.stringify(data));
  return Number(info.lastInsertRowid);
}

/**
 * Retrieve recent backups.
 * @param limit - Maximum number of backups to return (default 10).
 * @returns An array of backup objects with id, data (parsed), and created_at.
 */
export function getBackups(limit: number = 10) {
  const stmt = db.prepare(`SELECT id, data, created_at FROM backups ORDER BY created_at DESC LIMIT ?`);
  const rows = stmt.all(limit) as Array<{ id: number; data: string; created_at: string }>;
  return rows.map(r => ({
    id: r.id,
    data: JSON.parse(r.data) as JsonObject,
    created_at: r.created_at,
  }));
}
